/* Connected workflow views. Reuses the web2 shell, styles, map and role navigation. */
(() => {
  const live = {query:'',statusFilter:'all',tableLoading:false,tableRequest:0,rows:[], summary:null, health:null, loading:true, authRequired:false, scenarios:[], selected:null, busy:false, error:'', authority:null, selectionDraft:null, rationaleError:'', pendingProgress:null, token:'', table:'plants', tableRows:[], offset:0, total:0, trace:[]};
  const cities={PLT_MUM:'Mumbai',PLT_TYO:'Tokyo',PLT_BJS:'Beijing'};
  const stageNames=['Sentinel','Investigator','Impact','Recovery','Commander'];
  const labels={DRAFT:'Draft · review required',DETECTED:'Queued',ANALYZING:'Assessing',AWAITING_SELECTION:'Planner selection',AWAITING_APPROVAL:'Ready for release',APPROVED:'Ready for release',READY_FOR_EXECUTION:'Ready for release',MONITORING:'Execution monitoring',AWAITING_CLOSURE:'Outcome review',CHANGES_REQUESTED:'Changes requested',PLANNING_BLOCKED:'No feasible plan',ESCALATED:'Evidence review',RESOLVED:'Closed',FAILED:'Analysis failed'};
  const selected=()=>scopedRows().find(i=>i.id===live.selected)||scopedRows()[0];
  const displayTitle=value=>String(value||'').replaceAll('_',' ');
  const displayDate=value=>value?new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kolkata'}).format(new Date(value))+' IST':'Not recorded';
  const scopedRows=()=>live.rows.filter(i=>plant==='All plants'||cities[i.snapshot.event.plant_id]===plant);
  const number=value=>new Intl.NumberFormat('en-IN',{maximumFractionDigits:2}).format(value);
  const humanLabel=value=>String(value).replace(/_/g,' ').replace(/\b(id|sku|moq|inr|utc)\b/gi,m=>m.toUpperCase()).replace(/^./,c=>c.toUpperCase());
  const actionLabel=value=>({ALTERNATE_SUPPLIER:'Alternate supplier',TRANSFER:'Stock transfer',INTERPLANT_TRANSFER:'Interplant transfer'}[value]||humanLabel(value));
  function dataValue(value,depth=0){
    if(value===null||value===undefined||value==='')return '<span class="data-missing">Not provided</span>';
    if(typeof value==='boolean')return `<span class="data-boolean">${value?'Yes':'No'}</span>`;
    if(typeof value==='number')return `<span class="data-number">${number(value)}</span>`;
    if(typeof value==='object'){
      const entries=Array.isArray(value)?value.map((v,n)=>[String(n+1),v]):Object.entries(value);
      if(!entries.length)return '<span class="data-missing">None recorded</span>';
      if(depth>3)return `<span class="data-text">${esc(JSON.stringify(value))}</span>`;
      return `<details class="data-expand"><summary>${entries.length} ${Array.isArray(value)?'items':'fields'}</summary><dl class="data-properties">${entries.map(([k,v])=>`<div><dt>${esc(humanLabel(k))}</dt><dd>${dataValue(v,depth+1)}</dd></div>`).join('')}</dl></details>`;
    }
    return `<span class="data-text">${esc(value)}</span>`;
  }
  const quantity=value=>`<span class="data-number">${number(value)}</span>`;
  const table=(headers,rows)=>`<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable data table"><table><thead><tr>${headers.map(h=>`<th scope="col" class="${/^(Demand|Scheduled receipts|Uncovered units|Quantity|Capacity|Peak shortage)$/.test(h)?'numeric':''}">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
  const metric=(title,value,note)=>`<div class="metric"><div class="metric-label">${esc(title)}</div><div class="metric-value">${esc(typeof value==='number'?number(value):value)}</div><div class="metric-note">${esc(note)}</div></div>`;
  const statusBadge=i=>badge(esc(labels[i.status]||i.status),['APPROVED','READY_FOR_EXECUTION','RESOLVED'].includes(i.status)?'teal':'amber');
  async function request(path,method='GET',body) {
    const response=await fetch(path,{method,cache:'no-store',headers:{...(body?{'Content-Type':'application/json'}:{}),...(live.token?{Authorization:'Bearer '+live.token}:{})},...(body?{body:JSON.stringify(body)}:{})});
    const result=await response.json();
    if(!response.ok){const error=Error(typeof result.detail==='string'?result.detail:JSON.stringify(result.detail||result));error.status=response.status;throw error;}
    return result;
  }
  function sync(rows){live.rows=rows;window.workflowIncidents=rows;}
  async function refresh(){sync(await request('/api/workflow/incidents'));if(!live.selected&&live.rows.length)live.selected=live.rows[0].id;}
  async function action(fn){
    if(live.busy)return;
    const inputs=[...document.querySelectorAll('main input,main textarea,main select')].filter(e=>e.type!=='password').map(e=>({id:e.id,name:e.name,value:e.value,checked:e.checked}));
    live.busy=true;live.error='';document.querySelector('main')?.insertAdjacentHTML('afterbegin','<div class="work-status" role="status">Updating incident… Please wait.</div>');document.querySelector('main')?.setAttribute('aria-busy','true');document.querySelectorAll('main button').forEach(b=>b.disabled=true);
    let failed=false;
    try{await fn();await refresh();}catch(error){failed=true;live.error=error.message;toast(error.message);}
    finally{live.busy=false;render();if(failed){for(const saved of inputs){const e=[...document.querySelectorAll('main input,main textarea,main select')].find(e=>saved.id?e.id===saved.id:e.name===saved.name&&e.name&&(e.type!=='checkbox'||e.value===saved.value));if(e){e.value=saved.value;if(e.type==='checkbox')e.checked=saved.checked;}}}}
  }
  function nextStep(i){
    if(i.status==='DRAFT')return ['Review draft','Review the incident and evidence before assessing impact.','Incident'];
    if(['DETECTED','ANALYZING'].includes(i.status))return ['View assessment','The agents are assessing this incident.','Impact Assessment'];
    if(i.status==='AWAITING_SELECTION')return ['Compare plans','Compare timing, cost and constraints, then choose a recovery plan.','Recovery Planning'];
    if(['READY_FOR_EXECUTION','AWAITING_APPROVAL','APPROVED'].includes(i.status))return ['Review for release','Your selected plan is ready for simulated execution.','Recovery Planning'];
    if(i.status==='MONITORING')return ['Record progress','Record actual receipts and costs to track recovery.','Learning'];
    if(i.status==='AWAITING_CLOSURE')return ['Capture outcomes','Record the outcome and lessons to close this incident.','Learning'];
    if(i.status==='RESOLVED')return ['View outcomes','Review the recorded outcome and lessons.','Learning'];
    return ['Review incident','Review the evidence and resolve outstanding planning issues.','Incident'];
  }
  function focusPanel(){if(typeof focusMain==='function')focusMain();}
  function journey(i){
    const steps=[['Review','Incident',!!i.reviewed_by],['Assess','Impact Assessment',!!i.results.Impact],['Plan & release','Recovery Planning',!!i.action_id],['Track & learn','Learning',!!i.outcome]];
    return `<nav class="journey-nav" aria-label="Incident workflow"><ol>${steps.map(([label,page,done],n)=>`<li><button onclick="${page==='Incident'?`flow.open('${i.id}')`:`nav('${page}')`}" ${view===page?'aria-current="step"':''}><span class="journey-number" aria-hidden="true">${done?'✓':n+1}</span><span>${label}<small>${done?'Recorded':view===page?'Current view':'Open step'}</small></span></button></li>`).join('')}</ol></nav>`;
  }
  function workBrief(rows){
    const ordered=[...rows].filter(i=>i.status!=='RESOLVED').sort((a,b)=>({READY_FOR_EXECUTION:0,AWAITING_SELECTION:1,MONITORING:2,DRAFT:3}[a.status]??4)-({READY_FOR_EXECUTION:0,AWAITING_SELECTION:1,MONITORING:2,DRAFT:3}[b.status]??4));
    const i=ordered[0],step=i&&nextStep(i);
    return `<section class="work-brief" aria-label="Workspace briefing"><div class="brief-main"><span class="brief-eyebrow">YOUR OPERATIONS WORKSPACE</span><h2>${i?'A clear next step for every disruption.':'Ready for your next incident.'}</h2><p>Review the evidence. Compare your options. Track recovery with confidence.</p><div class="brief-trust"><span>Source-backed assessments</span><span>Simulated execution</span><span>Planner-controlled actions</span></div></div><div class="brief-action"><span class="brief-eyebrow">${i?'CONTINUE YOUR WORK':'GET STARTED'}</span><h3>${i?esc(displayTitle(i.scenario_title)):'Create an incident'}</h3><p>${i?esc(step[1]):'Describe a disruption or detect incidents from the supplied scenarios.'}</p><button class="primary" onclick="${i?`flow.advance('${i.id}')`:'flow.newDraft()'}">${i?esc(step[0]):'Create incident'} <span aria-hidden="true">→</span></button></div></section>`;
  }
  function queueFilters(){return `<form class="queue-filters" onsubmit="flow.filterIncidents(event)"><label for="incident-search">Find an incident<input id="incident-search" name="query" type="search" placeholder="Search title, ID, plant or material" value="${esc(live.query)}"></label><label for="incident-status">Workflow status<select id="incident-status" name="status"><option value="all">All statuses</option>${[...new Set(scopedRows().map(i=>i.status))].map(status=>`<option value="${status}" ${live.statusFilter===status?'selected':''}>${esc(labels[status]||status)}</option>`).join('')}</select></label><button type="submit">Apply filters</button>${live.query||live.statusFilter!=='all'?'<button type="button" class="quiet" onclick="flow.clearFilters()">Clear filters</button>':''}</form>`;}
  function row(i){const impact=i.results.Impact;return `<tr><td><button class="text-link incident-link" onclick="flow.open('${i.id}')">${esc(displayTitle(i.scenario_title))}</button><br><span class="muted tiny record-id">${esc(i.id)} · v${i.revision}</span></td><td>${esc(cities[i.snapshot.event.plant_id]||i.snapshot.event.plant_id)}</td><td>${esc(i.snapshot.event.material_id)}</td><td>${impact?number(impact.shortage_units)+' units':'Not assessed'}</td><td>${statusBadge(i)}</td><td><button class="small" onclick="flow.advance('${i.id}')" aria-label="${esc(nextStep(i)[0]+': '+displayTitle(i.scenario_title))}">${esc(nextStep(i)[0])} →</button></td></tr>`;}
  function queue(rows){const all=rows.length,filtered=view==='Incidents';if(filtered)rows=rows.filter(i=>(live.statusFilter==='all'||i.status===live.statusFilter)&&[i.scenario_title,i.id,i.snapshot.event.material_id,cities[i.snapshot.event.plant_id]].join(' ').toLowerCase().includes(live.query.toLowerCase()));return `<section class="card incident-queue"><div class="card-head"><div><h2>Incident workspace</h2><p>Open a record for evidence, or continue with its next step.</p></div><span class="queue-count" role="status">${rows.length}${filtered?' of '+all:''} incidents</span></div>${filtered?queueFilters():''}${rows.length?table(['Incident','Plant','Component revision','Peak shortage','Status','Next step'],rows.map(row)):`<div class="empty"><h3>${all?'No matching incidents':'No incidents in this view'}</h3><p>${all?'Try a different search or clear your filters.':'Create an incident or check the supplied scenario signals.'}</p>${all?'<button onclick="flow.clearFilters()">Clear filters</button>':''}</div>`}</section>`;}
  function scenarioLibrary(){const cases=live.scenarios.filter(s=>s.showcase);return head('Scenario library','Explore synthetic cases across plants, materials and recovery constraints.',badge(cases.length+' demo cases','teal'))+`<section class="card pad"><h2>Choose a case to investigate</h2><p>Each case creates a separate draft for review. These are synthetic overlays on the existing operational snapshot, not live disruption reports. Executed actions share the simulation ledger, so outcomes can change as inventory and capacity are committed.</p></section><div class="scenario-grid">${cases.map(s=>`<article class="card scenario-card"><div><span class="eyebrow">${esc(s.category)}</span><h2>${esc(s.title)}</h2><p class="scenario-location">${esc(cities[s.plant]||s.plant)} · ${esc(s.material)}</p><p>${esc(s.description)}</p><details><summary>Suggested questions for Res</summary><ul>${s.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul></details></div><button class="primary" onclick="flow.useScenario('${s.id}')">Review this scenario →</button></article>`).join('')}</div>`;}
  function sourceStatus(){const s=live.summary,h=live.health;return `<section class="card source-status-card"><div class="card-head"><div><h2>Connected operational data</h2><p>Synthetic source snapshot for this workspace.</p></div></div><div class="source-status-body"><dl class="source-coverage"><div><dt>Source records</dt><dd>${number(s?.row_count||0)}</dd></div><div><dt>Tables</dt><dd>${Object.keys(s?.table_counts||{}).length}</dd></div><div><dt>Supported scenarios</dt><dd>${live.scenarios.filter(s=>s.supported!==false).length}</dd></div></dl><details class="integration-details"><summary>Snapshot &amp; integration details</summary><p class="section-note">${esc(s?.version||'Source status unavailable')}</p><p class="section-note">${h?`Agents: ${esc(h.agent_mode)} · Retrieval: ${esc(h.retrieval_mode)} · Evidence: ${esc(h.evidence_mode)} · Execution: ${esc(h.execution)}`:'Checking service status…'}</p></details><div class="source-status-footer"><p>Review a detected draft, then select <strong>Assess Impact</strong> to generate impact and recovery results.</p><button onclick="nav('Data & Sources')">Browse source data <span aria-hidden="true">→</span></button></div></div></section>`;}
  function overviewView(){const rows=scopedRows(),active=rows.filter(i=>i.status!=='RESOLVED');return head('Operations overview','Your network, priorities and recovery work in one place.',badge('Operations workspace','teal'))+workBrief(rows)+`<div class="metrics">${metric('Open incidents',active.length,'Incidents not yet closed')}${metric('Awaiting assessment',rows.filter(i=>i.status==='DRAFT').length,'Drafts awaiting your review')}${metric('Ready for release',rows.filter(i=>['READY_FOR_EXECUTION','AWAITING_APPROVAL','APPROVED'].includes(i.status)).length,'Selected plans awaiting release')}${metric('Monitoring',rows.filter(i=>i.status==='MONITORING').length,'Released simulated actions')}</div>`+`<div class="scenario-library-link"><button onclick="nav('Scenario library')">Explore ${live.scenarios.filter(s=>s.showcase).length} demo scenarios →</button><span>Multi-plant cases · Evidence conflicts · Recovery trade-offs</span></div><div class="wf-intake-actions"><button class="card wf-action" onclick="flow.newDraft()"><span class="wf-action-icon">＋</span><span><b>Create incident</b><small>Enter details and evidence for review</small></span></button><button class="card wf-action" onclick="flow.scan()"><span class="wf-action-icon">◎</span><span><b>Detect incidents</b><small>Check the supplied scenario signals</small></span></button></div>`+`<div class="overview-context">${worldMap()}${sourceStatus()}</div>`+queue(rows);}
  function autofillPanel(){return `<section class="res-autofill"><h2>Autofill incident</h2><p class="section-note">Paste a shipment notice to suggest draft fields. Review the suggestions before applying; autofill does not verify evidence or run an assessment.</p><label class="field-label" for="autofill-notice">Shipment notice or description</label><textarea id="autofill-notice" maxlength="4000" placeholder="Example: Shipment SHIP_00144 delayed by 3 days. Supplier confirmation received today."></textarea><div class="actions"><button type="button" onclick="flow.suggestAutofill()">Suggest fields</button></div><div id="autofill-preview" aria-live="polite"></div></section>`;}
  let autofillSuggestions=null;
  function draftForm(i){const d=i?.draft||{title:'',description:'',evidence:'',scenario_id:'SCN_001',shipment_id:'',delay_days:0};return '<button class="quiet back-link" onclick="nav(\'Incidents\')">← All incidents</button>'+head(i?'Review incident draft':'Enter an incident','Confirm the operational context and evidence before clicking Assess.',badge(i?`Revision ${i.revision}`:'Manual entry','teal'))+(i?journey(i):'')+autofillPanel()+`<section class="card pad intake-card"><form id="incident-form" class="form" onsubmit="flow.saveDraft(event)"><label>Incident title<input name="title" maxlength="160" minlength="3" value="${esc(d.title)}" required></label><label>Description<textarea name="description" rows="3" maxlength="4000" required>${esc(d.description)}</textarea></label><label>Operational scenario<select name="scenario_id">${live.scenarios.filter(s=>s.supported!==false).map(s=>`<option value="${esc(s.id)}" ${d.scenario_id===s.id?'selected':''}>${esc(s.id+' · '+displayTitle(s.title))}</option>`).join('')}</select></label><details><summary>Enter an outstanding shipment directly</summary><p class="section-note">A shipment ID overrides the scenario selection. Only known outstanding shipments and exact component revisions are accepted.</p><label>Shipment ID<input name="shipment_id" value="${esc(d.shipment_id||'')}" placeholder="SHIP_00144"></label><label>Reported delay (days)<input name="delay_days" type="number" min="0" max="30" value="${d.delay_days||0}"></label></details><label>Evidence / source notes<textarea name="evidence" rows="3" maxlength="8000">${esc(d.evidence)}</textarea></label><div class="actions"><button class="primary" type="submit">Save draft</button>${i?'<button type="button" onclick="flow.assess()">Assess Impact →</button>':''}</div><p class="section-note">Assessment uses the saved draft. Save any changes first. Scenario signals are synthetic overlays, not live external disruption claims.</p></form></section>`;}
  function timeline(i){return `<section class="card"><div class="card-head"><h2>Workflow progress</h2><span class="muted tiny">REVISION ${i.revision}</span></div><div class="pad timeline">${[['Draft reviewed',i.reviewed_by],...stageNames.map(s=>[s,i.results[s]]),['Planner selected plan',i.selected_plan_id],['Released for execution',i.action_id],['Outcome captured',i.outcome]].map(([name,done],n)=>`<div class="step"><span class="step-num">${done?'✓':n+1}</span><div>${esc(name)}<small>${done?'Recorded':'Pending'}</small></div></div>`).join('')}</div></section>`;}
  function impactView(i){const r=i.results.Impact;if(!r)return `<section class="card empty" role="status"><h2>${['DETECTED','ANALYZING'].includes(i.status)?'Assessing impact…':'Impact assessment unavailable'}</h2><p>${esc(i.error||(['DETECTED','ANALYZING'].includes(i.status)?'The agents are retrieving evidence, reasoning and calculating exposure. Gemini quota pacing may take several minutes. Results will appear here automatically.':'Review the incident evidence and try again.'))}</p></section>`;return agentReasoning(i,['Impact'])+`<div class="metrics">${metric('Usable stock',r.available_units,'Exact material revision')}${metric('Peak uncovered units',r.shortage_units,'Across the planning horizon')}${metric('First shortage',r.first_shortage_day?'Day '+r.first_shortage_day:'None','Receipts included in daily buckets')}${metric('Affected entities',r.affected_entities.length,'Dependency graph')}</div><section class="card"><div class="card-head"><h2>Impact report</h2><button onclick="flow.downloadPdf('impact',this)">Download impact report (PDF)</button></div><div class="pad"><p>${esc(i.snapshot.source_metadata.scope||'Synthetic planning snapshot')}</p><div class="data-section-label">Related entities</div><div class="entity-chips">${r.affected_entities.slice(0,6).map(e=>`<span>${esc(e)}</span>`).join('')||'<span class="data-missing">None identified</span>'}</div>${r.affected_entities.length>6?`<details class="entity-details"><summary>View all ${number(r.affected_entities.length)} related entities</summary><div class="entity-chips">${r.affected_entities.map(e=>`<span>${esc(e)}</span>`).join('')}</div></details>`:''}<div class="exposure-summary"><span class="data-secondary">Related order value</span><strong>${r.order_exposure?money(r.order_exposure.potential_order_value_paise/100):'Not valued'}</strong><span class="data-secondary">${r.order_exposure?'Modeled exposure, not realized financial loss.':'No verified loss model is available.'}</span></div></div>${table(['Day','Demand','Scheduled receipts','Uncovered units'],r.timeline.map(t=>`<tr><td><span class="day-label">Day ${t.day}</span></td><td class="numeric">${quantity(t.demand)}</td><td class="numeric">${quantity(t.scheduled_receipts||0)}</td><td class="numeric"><span class="${t.cumulative_shortage>0?'shortage-value':'data-muted'}">${quantity(t.cumulative_shortage)}</span></td></tr>`))}</section>`;}
  function constraints(i){if(role!=='Planner'||!['AWAITING_SELECTION','PLANNING_BLOCKED','CHANGES_REQUESTED','AWAITING_APPROVAL','APPROVED','READY_FOR_EXECUTION','ESCALATED'].includes(i.status))return '';const d=i.snapshot;return `<section class="card pad"><h2>Reject options or revise constraints</h2><p class="section-note">Replanning creates a new revision and invalidates the previous selection. Qualification and source costs cannot be overridden.</p><form class="form" onsubmit="flow.replan(event)"><label>Maximum cost (INR, optional)<input name="budget" type="number" min="0" step="0.01" value="${d.max_cost_paise===null?'':d.max_cost_paise/100}"></label><label>Latest arrival day (optional)<input name="deadline" type="number" min="1" max="30" value="${d.latest_arrival_day||''}"></label><fieldset><legend>Exclude options</legend>${d.options.map(o=>`<label><input type="checkbox" name="excluded" value="${esc(o.id)}" ${d.excluded_option_ids.includes(o.id)?'checked':''}> ${esc(o.source_id+' · '+o.action_type+' · day '+o.arrival_day)}</label>`).join('')}</fieldset><label>Reason / requested changes<textarea name="reason" minlength="3" maxlength="2000" required></textarea></label><button class="primary">Reassess and replan</button></form></section>`;}
  function recoveryView(i){const plans=i.candidates||[];return agentReasoning(i,['Recovery','Commander'])+`${i.results.Recovery?`<section class="card pad"><button onclick="flow.downloadPdf('recovery',this)">Download recovery report (PDF)</button><p class="section-note">Includes all generated plans, saved selection, constraints and source references.</p></section>`:''}<section class="card"><div class="card-head"><div><h2>Feasible recovery options</h2><p>Compare complete plans, then select one for release.</p></div>${badge(plans.length+' '+(plans.length===1?'plan':'plans'),'teal')}</div><div class="pad">${!plans.length?`<div class="callout"><h3>${i.plan?.status==='NO_ACTION'?'No recovery needed':'No feasible plan yet'}</h3><p>${esc(i.error||'Assess the draft or revise planning constraints.')}</p></div>`:plans.map(p=>`<article class="option ${p.id===i.selected_plan_id?'is-selected':''}"><div class="option-heading"><h3>Recovery plan ${plans.indexOf(p)+1}</h3>${p.id===i.selected_plan_id?badge('Selected plan','teal'):''}</div><p class="record-id muted">${esc(p.id)}</p><div class="plan-price"><div><span class="data-secondary">Estimated recovery cost</span><strong>${money(p.total_cost_paise/100)}</strong></div>${badge(p.status==='OPTIMAL'?'Optimal within modeled constraints':humanLabel(p.status),'teal')}</div><p class="section-note">Policy: ${esc(p.approval_policy)} · Review cost assumptions before release.</p>${table(['Action / source','Quantity','Arrival'],p.allocations.map(a=>{const o=i.snapshot.options.find(o=>o.id===a.option_id);return `<tr><td><span class="data-primary">${esc(actionLabel(o.action_type))}</span><span class="data-secondary">${esc(o.source_id)}</span></td><td class="numeric">${quantity(a.quantity)} <span class="data-unit">units</span></td><td>Day ${o.arrival_day}</td></tr>`;}))}${role==='Planner'&&i.status==='AWAITING_SELECTION'?`<button class="primary" onclick="flow.choose('${p.id}')">Select this plan</button>`:''}</article>`).join('')}<details><summary>Constraints and source evidence</summary>${table(['Source','Capacity','MOQ / multiple','Arrival','Status'],i.snapshot.options.map(o=>`<tr><td>${esc(o.id)}</td><td>${o.capacity}</td><td>${o.minimum_order_qty} / ${o.order_multiple}</td><td>Day ${o.arrival_day}</td><td>${esc(i.results.Recovery?.excluded_options?.[o.id]||'Eligible candidate')}</td></tr>`))}</details></div></section>${i.status==='AWAITING_SELECTION'&&role==='Planner'?`<section class="card pad">${live.rationaleError?`<p role="alert" class="section-note">${esc(live.rationaleError)}</p>`:''}<label class="field-label">Selection rationale<textarea id="selection-rationale" rows="2" maxlength="2000" placeholder="Select a plan to generate its rationale" oninput="flow.editRationale(this.value)">${live.selectionDraft?.incident_id===i.id&&live.selectionDraft?.revision===i.revision?esc(live.selectionDraft.rationale):''}</textarea></label><label class="check-label"><input type="checkbox" id="confirm-assumptions"> I reviewed timing, qualification and cost assumptions, including any unquoted costs.</label>${live.selectionDraft?.incident_id===i.id&&live.selectionDraft?.revision===i.revision?`<p class="section-note">Generated by the Recovery agent for ${esc(live.selectionDraft.plan_id)}. Review or edit before confirming.</p>${live.selectionDraft.stale?'<div class="callout"><p>Relevant planning data has changed. The rationale describes the saved analysis. Refresh recovery plans before selecting.</p><button class="primary" onclick="flow.refreshStalePlans()">Refresh recovery plans</button></div>':'<button class="primary" onclick="flow.confirmSelection()">Confirm plan selection</button>'}`:''}</section>`:''}${constraints(i)}`;}
  function releaseView(i){return `${['READY_FOR_EXECUTION','AWAITING_APPROVAL','APPROVED'].includes(i.status)?'<section class="card pad"><h2>Release selected plan</h2><p>The plan is ready. Release starts simulated execution after checking current inventory and planning constraints.</p><button class="primary" onclick="flow.release()">Release for simulated execution</button></section>':''}`;}

  function progressView(i){const p=i.plan;if(!p)return '<section class="card empty">No plan has been released.</section>';return `<section class="card pad"><h2>Recovery dashboard and actuals</h2><div class="progress-track">${[['Selected',i.selected_plan_id],['Released',i.action_id],['Actuals',i.progress?.length],['Closed',i.outcome]].map(([label,done])=>`<span class="${done?'done':''}">${done?'✓ ':''}${label}</span>`).join('')}</div><div class="cost-comparison"><div><span class="data-secondary">Estimated plan cost</span><strong>${money(p.total_cost_paise/100)}</strong></div><div><span class="data-secondary">Recorded actual cost</span><strong>${money((i.actual_cost_paise||0)/100)}</strong></div></div><p class="section-note">All actions and receipts here are simulated. Record observed quantities; a successful API response is not a delivery confirmation.</p></section>${i.status==='MONITORING'?`<section class="card pad"><form class="form" onsubmit="flow.progress(event)"><h3>Record progress</h3>${p.allocations.map(a=>`<label>Cumulative received: ${esc(a.option_id)} (planned ${a.quantity})<input type="number" name="received:${esc(a.option_id)}" min="0" max="${a.quantity}" value="${latestReceived(i,a.option_id)}" required></label>`).join('')}<label>Cumulative actual cost (INR)<input type="number" name="cost" min="0" step="0.01" value="${(i.actual_cost_paise||0)/100}" required></label><label>As of planning day<input type="number" name="day" min="${i.actuals_as_of_day||1}" max="30" value="${i.actuals_as_of_day||1}" required></label><details><summary>Inventory actuals since the last update</summary><p>Enter only new quantities not recorded previously.</p><label>Scheduled receipts actually received<input type="number" name="scheduled" min="0" value="0"></label><label>Actual consumption<input type="number" name="consumed" min="0" value="0"></label></details><label>Progress evidence / notes<textarea name="note" minlength="3" maxlength="2000" required></textarea></label><label><input type="checkbox" name="deviation"> Material deviation: cancel the unreceived remainder and reassess.</label><p class="section-note">Overdue outstanding quantities and cost overruns also trigger reassessment. Completed receipts remain recorded; the previous selection is invalidated.</p><button class="primary">Record actuals</button></form></section>`:''}${i.status==='AWAITING_CLOSURE'?`<section class="card pad"><h2>Close incident and capture outcomes</h2><form class="form" onsubmit="flow.close(event)"><label>Outcome<textarea name="outcome" minlength="3" maxlength="4000" required></textarea></label><label>Lessons for future incidents<textarea name="lessons" minlength="3" maxlength="4000" required></textarea></label><button class="primary">Close incident</button></form></section>`:''}${i.outcome?`<section class="card pad"><h2>Outcome and learning record</h2><p>${esc(i.outcome.summary)}</p><h3>Lessons captured</h3><p>${esc(i.outcome.lessons)}</p><p>Cost variance: ${money(i.outcome.cost_variance_paise/100)}</p><p class="section-note">${esc(i.outcome.scope)}</p></section>`:''}`;}
  function latestReceived(i,id){const updates=i.progress.filter(p=>p.request.revision===i.revision);let qty=0;for(const p of updates)if(p.request.received_units[id]!==undefined)qty=p.request.received_units[id];return qty;}
  function evidenceDocument(e){
    if(e.id==='EV-CONTEXT-EXTRACTION'&&e.value?.facts){const r=e.value;return `<section class="card pad"><div class="option-heading"><h2>Gemini evidence extraction</h2>${badge(humanLabel(r.family)+' / '+r.subtype,'teal')}</div>${r.facts.map(f=>`<section class="evidence-section"><p>${esc(f.interpretation)}</p><blockquote>${esc(f.quote)}</blockquote><p class="section-note">Source: ${esc(f.source_id)}</p></section>`).join('')}${r.uncertainties?.length?`<details><summary>Uncertainty and missing information</summary><ul>${r.uncertainties.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></details>`:''}<p class="section-note">${esc(r.scope)}</p></section>`;}

    const text=String(e.value?.text||e.explanation||'');
    const paragraphs=text.replace(/\r\n?/g,'\n').split(/\n\s*\n/).filter(p=>p.trim());
    const agreement=/^-\s+([^:]+):\s+(\S+) to (\S+), ([^,]+), ([^,]+), ([\d.]+) ([^,]+), minimum (\d+), multiple (\d+)\.$/;
    const sectionTitle=p=>/^Configured processing lead time/.test(p)?'Lead time and capacity':/^Configured outbound hub/.test(p)?'Transport dependencies':/^\d+ shipment lines/.test(p)?'Historical performance':/^No real financial statements/.test(p)?'Evidence limits and required checks':null;
    const content=paragraphs.map((p,index)=>{
      const lines=p.trim().split('\n'),rows=lines.map(line=>line.trim().match(agreement));
      if(rows.length&&rows.every(Boolean))return `<section class="evidence-section evidence-agreements"><h4>Supply agreements</h4><p class="evidence-hint">Price per unit, minimum order quantity and order multiples from this source.</p>${table(['Material / source','Destination','Qualification / priority','Unit price','Minimum order','Order multiple'],rows.map(r=>`<tr><td><span class="data-primary">${esc(r[2])}</span><span class="data-secondary">${esc(r[1])}</span></td><td>${esc(cities[r[3]]||r[3])}<span class="data-secondary">${esc(r[3])}</span></td><td>${esc(humanLabel(r[4].toLowerCase()))}<span class="data-secondary">${esc(humanLabel(r[5]))}</span></td><td><span class="data-number">${esc(r[6])}</span> ${esc(r[7])}</td><td>${esc(r[8])} units</td><td>${esc(r[9])} units</td></tr>`))}</section>`;
      if(lines.every(line=>/^\s*[-*•]\s/.test(line)))return `<ul class="evidence-list">${lines.map(line=>`<li>${esc(line.replace(/^\s*[-*•]\s/,''))}</li>`).join('')}</ul>`;
      const heading=sectionTitle(p);
      return `<section class="evidence-section ${heading==='Evidence limits and required checks'?'evidence-limits':''}">${heading?`<h4>${heading}</h4>`:index===0?'<h4>Source overview</h4>':''}<p>${esc(p)}</p></section>`;
    }).join('');
    return `<article class="card evidence-document"><div class="card-head"><div><span class="evidence-eyebrow">Supporting evidence</span><h3>${esc(e.source)}</h3></div></div><div class="pad">${content}<details class="evidence-original"><summary>View original source text</summary><div>${esc(text)}</div></details></div></article>`;
  }
  function agentReasoning(i,names=stageNames){const reviews=i.agent_reviews||{};return names.filter(n=>reviews[n]).map(n=>{const r=reviews[n];return `<section class="card pad"><div class="option-heading"><h2>${esc(n)} assessment</h2>${badge(r.verdict==='needs_review'?'Review needed':'Gemini assessment',r.verdict==='needs_review'?'amber':'teal')}</div><p>${esc(r.summary)}</p>${r.recommended_plan_id?`<p><strong>Recommended plan:</strong> ${esc(r.recommended_plan_id)}</p>`:''}${r.uncertainties?.length?`<details><summary>Assumptions and uncertainty</summary><ul>${r.uncertainties.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></details>`:''}<p><strong>Next step:</strong> ${esc(r.next_action)}</p><p class="section-note">Evidence: ${r.evidence_ids.map(esc).join(' · ')} · ${esc(r.model)}</p></section>`;}).join('');}
  function signalMonitoring(i){const r=i.results?.Sentinel?.disruption_monitoring;if(!r?.signals?.length)return '';return `<section class="card"><div class="card-head"><h2>Disruption monitoring</h2>${badge(r.anomalies+' '+(r.anomalies===1?'anomaly':'anomalies'),'amber')}</div><div class="pad"><p>${esc(r.scope)}</p></div>${table(['Family / signal','Observed / baseline','Historical samples','Assessment'],r.signals.map(s=>`<tr><td>${esc(humanLabel(s.family)+' / '+s.subtype)}<span class="data-secondary">${esc(s.metric)}</span></td><td>${number(s.observed_value)} / ${number(s.baseline_median)} ${esc(s.unit)}</td><td>${s.baseline_samples}<span class="data-secondary">${esc(s.baseline_start+' to '+s.baseline_end)}</span></td><td>${s.anomaly?'Anomaly - investigate':'Within expected range'}<span class="data-secondary">Robust z: ${s.adverse_robust_z}</span></td></tr>`))}</section>`;}
  function evidenceView(i){return signalMonitoring(i)+agentReasoning(i)+`<section class="card pad"><h2>Incident evidence</h2><p>${esc(i.draft.description)}</p><blockquote>${esc(i.draft.evidence||'No additional operator evidence supplied.')}</blockquote><p>Source: ${esc(i.snapshot.event.source)}</p><details><summary>Planning assumptions</summary><ul>${(i.snapshot.source_metadata.limitations||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details></section>${Object.values(i.evidence).filter(e=>e.kind==='DOCUMENT').map(evidenceDocument).join('')}`;}
  function audit(i){return `<section class="card"><div class="card-head"><h2>Activity &amp; decision history</h2><button onclick="flow.audit()">Refresh audit</button></div>${table(['Time','Actor','Event'],live.trace.map(t=>`<tr><td>${esc(displayDate(t.at))}</td><td>${esc(t.agent)}</td><td>${esc(humanLabel(t.kind))}</td></tr>`))}<div class="pad"><h3>Prior planning revisions</h3>${(i.history||[]).map(h=>`<p>Revision ${h.revision}: ${esc(h.reason)} · ${esc(h.status)}</p>`).join('')||'<p>No prior revisions.</p>'}</div></section>`;}
  function detailView(i){
    if(!i)return queue(scopedRows());
    if(i.status==='DRAFT')return draftForm(i);
    const d=i.draft,event=i.snapshot.event;
    const facts=[['Incident ID',i.id],['Status',labels[i.status]||i.status],['Plant',cities[event.plant_id]||event.plant_id],['Material revision',event.material_id],['Scenario',d.scenario_id||'Manual incident'],['Shipment',d.shipment_id||i.snapshot.source_metadata?.target_shipments?.join(', ')||'See source evidence'],['Reported delay',d.shipment_id?`${d.delay_days} days`:'See scenario evidence'],['Planning revision',i.revision]];
    return '<button class="quiet back-link" onclick="nav(\'Incidents\')">← All incidents</button>'+head(esc(displayTitle(i.scenario_title)),'Incident details and supporting evidence.',statusBadge(i))+journey(i)+`<section class="card pad"><h2>Incident details</h2><dl class="incident-facts">${facts.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><div class="actions"><button class="primary" onclick="nav('Impact Assessment')">Assess Impact</button></div></section>${evidenceView(i)}${i.error?`<div class="callout" role="alert">${esc(i.error)}</div>`:''}`;
  }
  function sourcesView(){const s=live.summary;if(!s)return '<section class="card empty">Loading source data…</section>';const columns=live.tableRows.length?Object.keys(live.tableRows[0]):[];return head('Data & sources','Source records, coverage and provenance.',badge('resilientops_data','teal'))+`<div class="health-grid"><section class="card pad"><div class="eyebrow">OPERATIONAL BASELINE</div><h2>${Number(s.row_count||0).toLocaleString()} records</h2><p>${esc(s.version)}</p><p>${esc(displayDate(s.decision_time_utc))}</p></section><section class="card pad"><div class="eyebrow">PUBLIC REFERENCES</div><h2>Archived context</h2><p>${esc(s.reference_scope)}</p></section></div><section class="card pad source-browser"><label class="field-label">Source table<select id="source-table" onchange="flow.table(this.value)">${Object.entries({...s.table_counts,...Object.fromEntries(Object.entries(s.reference_sources||{}).map(([k,v])=>['reference:'+k,v]))}).map(([k,v])=>`<option value="${esc(k)}" ${k===live.table?'selected':''}>${esc(humanLabel(k))} (${number(v)})</option>`).join('')}</select></label><div class="source-summary"><span class="data-section-label">${esc(humanLabel(live.table))}</span><span class="data-secondary">Showing ${number(live.total?live.offset+1:0)}–${number(Math.min(live.offset+50,live.total))} of ${number(live.total)} records</span></div>${live.tableLoading?'<div class="data-loading" role="status">Loading source records…</div>':live.tableRows.length?table(columns.map(humanLabel),live.tableRows.map(r=>`<tr>${columns.map(k=>`<td>${dataValue(r[k])}</td>`).join('')}</tr>`)):'<div class="empty">No records available in this source.</div>'}<div class="actions pagination"><button onclick="flow.page(-1)" ${live.tableLoading||live.offset===0?'disabled':''}>Previous</button><button onclick="flow.page(1)" ${live.tableLoading||live.offset+50>=live.total?'disabled':''}>Next</button></div></section>`;}
  const oldRender=render;
  render=function(){const focusedId=document.activeElement?.id,wasHeading=document.activeElement?.matches('main h1');oldRender();const main=document.getElementById('main-content');if(main&&live.error)main.insertAdjacentHTML('afterbegin',`<div class="callout" role="alert" tabindex="-1"><p>${esc(live.error)}</p><button onclick="flow.reload()">Retry connection</button>${live.authRequired?' <a href="/auth/google/login">Sign in with Google</a>':''}</div>`);if(live.error)main?.querySelector('[role=alert]')?.focus({preventScroll:true});if(live.busy)document.querySelectorAll('main button').forEach(b=>b.disabled=true);if(typeof enhanceAccessibility==='function')enhanceAccessibility();if(main)main.setAttribute('aria-busy',String(live.busy));if(wasHeading)focusPanel();else if(focusedId)document.getElementById(focusedId)?.focus({preventScroll:true});};
  pageContent=function(){if(view==='Scenario library'&&live.summary)return scenarioLibrary();if(!live.summary)return head(live.loading?'Loading workspace':'Source data unavailable',live.loading?'Connecting to operational data and saved decisions.':'The source request failed. Retry or sign in again.');if(view==='New incident')return draftForm(null);if(view==='Data & Sources')return sourcesView();if(view==='Incident'||view==='Decision package')return detailView(selected());if(view==='Recovery Plans'){const i=selected();return i?head('Recovery plans','Compare feasible plans and prepare a versioned decision package.')+recoveryView(i):queue(scopedRows());}if(view==='Approvals'||view==='Pending approvals')return head('Ready for release','Release a selected plan for simulated execution.')+queue(scopedRows().filter(i=>['READY_FOR_EXECUTION','AWAITING_APPROVAL','APPROVED'].includes(i.status)));if(view==='Execution status')return head('Execution status','Track actuals and material deviations.')+queue(scopedRows().filter(i=>['MONITORING','AWAITING_CLOSURE','RESOLVED'].includes(i.status)));if(view==='Decision history')return head('Decision history','Persistent decisions and captured outcomes.')+queue(scopedRows().filter(i=>i.decision_history.length||i.outcome));return overviewView();};
  selectPlant=function(p){plant=p;live.selected=scopedRows()[0]?.id||null;live.trace=[];render();if(view==='Learning'&&selected())flow.audit();};
  navigation=function(){return [['Overview','◫'],['Incidents','◎'],['Impact Assessment','◈'],['Recovery Planning','⇄'],['Learning','◷'],['Data & Sources','▤']]};
  const connectedPage=pageContent;
  const context=()=>`<div class="wf-context"><label>Incident <select aria-label="Selected incident" onchange="flow.selectContext(this.value)">${scopedRows().map(i=>`<option value="${esc(i.id)}" ${i.id===live.selected?'selected':''}>${esc(displayTitle(i.scenario_title))} · ${esc(labels[i.status])}</option>`).join('')}</select></label><div class="context-actions"><button onclick="flow.askRes()" class="res-context-button">✧ Ask Res</button><button onclick="nav('Data & Sources')">Source data</button></div></div>`+journey(selected());
  pageContent=function(){
    if(!live.summary)return connectedPage();
    if(view==='Incidents')return head('Incidents','Review saved drafts and operational evidence.','<button class="primary" onclick="flow.newDraft()">Create incident</button>')+queue(scopedRows());
    if(['Impact Assessment','Recovery Planning','Learning'].includes(view)){
      const i=selected();if(!i)return head(view,'Select or create an incident to begin.')+queue(scopedRows());
      if(i.status==='DRAFT')return head(view,'Results appear after you review and assess this draft.')+context()+`<section class="card empty"><h2>Assessment required</h2><p>${esc(displayTitle(i.scenario_title))} is still a draft. Review the details and evidence before running the agents.</p><button class="primary" onclick="flow.open('${i.id}')">Review incident draft</button></section>`;
      if(view==='Impact Assessment')return head('Impact Assessment',esc(displayTitle(i.scenario_title)))+context()+impactView(i)+`<section class="card pad"><h2>Next: Recovery planning</h2><p class="section-note">${i.results.Recovery?'Recovery options were prepared with this assessment. Continue to compare plans and review feasibility.':'Complete the assessment before continuing to recovery planning.'}</p><button class="primary" onclick="flow.generateRecovery()" ${!i.results.Impact||!i.results.Recovery||['DETECTED','ANALYZING'].includes(i.status)?'disabled':''}>Generate Recovery Plan</button></section>`;
      if(view==='Recovery Planning')return head('Recovery Planning',esc(displayTitle(i.scenario_title)))+context()+recoveryView(i)+releaseView(i);
      return head('Learning','Track recovery actuals, deviations and captured outcomes.')+context()+progressView(i)+audit(i);
    }
    return connectedPage();
  };
  nav=function(v){view=v;live.error='';render();window.scrollTo(0,0);if(v==='Data & Sources')flow.table(live.table);if(v==='Learning'&&selected())flow.audit();focusPanel();};
  window.flow={
    useScenario(id){const spec=live.scenarios.find(s=>s.id===id&&s.showcase);if(!spec)return;action(async()=>{const saved=await request('/api/workflow/incidents','POST',{title:spec.title,description:spec.description,evidence:'Synthetic showcase '+spec.id+'. Review assumptions before assessing. '+spec.description,scenario_id:spec.id});live.selected=saved.id;view='Incident';toast('Scenario draft created. Review the evidence, then assess impact.');});},
    chatContext(){return ['Incident','Impact Assessment','Recovery Planning','Learning'].includes(view)?selected():null;},
    askRes(){const questions={'Impact Assessment':'Explain the main risks and uncertainties for this incident.','Recovery Planning':'Help me compare the recovery options, costs and timing.','Learning':'What progress should I record and what should I watch for?'};window.ResAssistant?.open(questions[view]||'What should I do next for this incident?');},
    advance(id){const i=live.rows.find(i=>i.id===id);if(!i)return;live.selected=id;const page=nextStep(i)[2];if(page==='Incident')flow.open(id);else nav(page);},
    filterIncidents(event){event.preventDefault();const fields=new FormData(event.target);live.query=String(fields.get('query')||'').trim();live.statusFilter=String(fields.get('status')||'all');render();document.getElementById('incident-search')?.focus();},
    clearFilters(){live.query='';live.statusFilter='all';render();document.getElementById('incident-search')?.focus();},
    suggestAutofill(){
      const notice=document.getElementById('autofill-notice').value.trim();
      if(notice.length<3){toast('Paste a shipment notice first.');return;}
      const values={title:notice.split(/[\n.!?]/)[0].slice(0,160),description:notice,evidence:notice};
      const shipment=notice.match(/\bSHIP_[A-Z0-9_]+\b/i),delay=notice.match(/\bdelay(?:ed)?(?:\s+by|\s+of)?\s+(\d+)\s+days?\b/i),scenario=notice.match(/\bSCN_\d{3}\b/i);
      if(shipment)values.shipment_id=shipment[0].toUpperCase();
      if(delay&&Number(delay[1])<=30)values.delay_days=Number(delay[1]);
      if(scenario&&live.scenarios.some(s=>s.id===scenario[0].toUpperCase()&&s.supported!==false))values.scenario_id=scenario[0].toUpperCase();
      autofillSuggestions=values;
      const labels={title:'Title',description:'Description',evidence:'Evidence notes',shipment_id:'Shipment ID (unverified)',delay_days:'Delay in days',scenario_id:'Scenario'};
      document.getElementById('autofill-preview').innerHTML=`<h3>Review suggested fields</h3><dl>${Object.entries(values).map(([k,v])=>`<dt>${esc(labels[k])}</dt><dd>${esc(v)}</dd>`).join('')}</dl><p class="section-note">Applying replaces the fields listed above. Other fields stay unchanged. Verify the selected scenario, shipment ID and delay before saving.</p><div class="actions"><button type="button" class="primary" onclick="flow.applyAutofill()">Apply suggestions</button><button type="button" onclick="flow.discardAutofill()">Discard</button></div>`;
    },
    applyAutofill(){if(!autofillSuggestions)return;const form=document.getElementById('incident-form');for(const [name,value] of Object.entries(autofillSuggestions)){const field=form.elements.namedItem(name);if(field)field.value=value;}if(autofillSuggestions.shipment_id)form.querySelector('details').open=true;flow.discardAutofill();form.elements.namedItem('title').focus();toast('Suggestions applied. Review the draft, then save.');},
    discardAutofill(){autofillSuggestions=null;document.getElementById('autofill-preview').replaceChildren();},
    generateRecovery(){const i=selected();if(!i?.results.Impact||!i?.results.Recovery||['DETECTED','ANALYZING'].includes(i.status))return;nav('Recovery Planning');},
    reload(){return initialize();},
    selectContext(id){live.selected=id;live.trace=[];render();if(view==='Learning')flow.audit();},
    current(){return selected();},
    open(id){window.scrollTo(0,0);live.selected=id;view='Incident';live.trace=[];render();focusPanel();},
    tab(value){tab=value;render();if(value==='Activity')flow.audit();},
    newDraft(){window.scrollTo(0,0);live.selected=null;view='New incident';render();focusPanel();},
    scan(){action(async()=>{const result=await request('/api/workflow/detect','POST',{});toast(`${result.incidents.length} scenario drafts available for review`);});},
    saveDraft(event){event.preventDefault();const f=Object.fromEntries(new FormData(event.target));const i=view==='New incident'?null:selected();const body={title:f.title,description:f.description,evidence:f.evidence,scenario_id:f.scenario_id,shipment_id:f.shipment_id.trim()||null,delay_days:Number(f.delay_days)};action(async()=>{const saved=await request(i?`/api/workflow/incidents/${i.id}/draft`:'/api/workflow/incidents',i?'PUT':'POST',i?{...body,revision:i.revision}:body);live.selected=saved.id;view='Incident';toast('Draft saved. Review, then Assess.');});},
    assess(){const i=selected();action(async()=>{await request(`/api/workflow/incidents/${i.id}/assess`,'POST',{revision:i.revision});view='Impact Assessment';tab='Impact';window.scrollTo(0,0);});},
    replan(event){event.preventDefault();const f=new FormData(event.target),i=selected();const body={revision:i.revision,max_cost_paise:f.get('budget')===''?null:Math.round(Number(f.get('budget'))*100),latest_arrival_day:f.get('deadline')===''?null:Number(f.get('deadline')),excluded_option_ids:f.getAll('excluded'),reason:f.get('reason')};action(async()=>{await request(`/api/workflow/incidents/${i.id}/replan`,'POST',body);view='Impact Assessment';tab='Impact';});},
    editRationale(value){if(live.selectionDraft)live.selectionDraft.rationale=value;},
    choose(id){const i=selected();live.rationaleError='';live.selectionDraft=null;action(async()=>{try{const result=await request(`/api/workflow/incidents/${i.id}/candidates/${encodeURIComponent(id)}/rationale?revision=${i.revision}`);live.selectionDraft={...result,incident_id:i.id};}catch(error){live.rationaleError='Could not generate rationale: '+error.message;throw error;}}).then(()=>{document.getElementById('selection-rationale')?.focus();});},
    refreshStalePlans(){const i=selected();action(async()=>{await request(`/api/workflow/incidents/${i.id}/replan`,'POST',{revision:i.revision,max_cost_paise:i.snapshot.max_cost_paise,latest_arrival_day:i.snapshot.latest_arrival_day,excluded_option_ids:i.snapshot.excluded_option_ids,reason:'Refresh recovery options after planning data changed'});live.selectionDraft=null;live.rationaleError='';view='Impact Assessment';});},
    confirmSelection(){const i=selected(),draft=live.selectionDraft;if(!draft||draft.stale||draft.incident_id!==i.id||draft.revision!==i.revision)return;const id=draft.plan_id;const rationale=document.getElementById('selection-rationale').value;const confirm_assumptions=document.getElementById('confirm-assumptions').checked;if(!rationale.trim()){document.getElementById('selection-rationale').focus();toast('Add a selection rationale before choosing a plan.');return;}if(!confirm_assumptions){document.getElementById('confirm-assumptions').focus();toast('Review and acknowledge the plan assumptions.');return;}action(async()=>{await request(`/api/workflow/incidents/${i.id}/select`,'POST',{revision:i.revision,plan_id:id,rationale,confirm_assumptions});view='Recovery Planning';tab='Approval';});},
    release(){const i=selected();action(async()=>{await request(`/api/workflow/incidents/${i.id}/release`,'POST',{plan_hash:i.plan_hash});view='Learning';tab='Execution & Outcomes';});},
    progress(event){event.preventDefault();const f=Object.fromEntries(new FormData(event.target)),i=selected();const received_units=Object.fromEntries(Object.entries(f).filter(([k])=>k.startsWith('received:')).map(([k,v])=>[k.slice(9),Number(v)]));const body={revision:i.revision,received_units,actual_cost_paise:Math.round(Number(f.cost)*100),note:f.note,material_deviation:f.deviation==='on',as_of_day:Number(f.day),consumed_units:Number(f.consumed),scheduled_received_units:Number(f.scheduled)};const key=JSON.stringify([i.id,body]);if(live.pendingProgress?.key!==key)live.pendingProgress={key,update_id:crypto.randomUUID()};body.update_id=live.pendingProgress.update_id;action(async()=>{const result=await request(`/api/workflow/incidents/${i.id}/progress`,'POST',body);live.pendingProgress=null;if(result.status==='DETECTED'){view='Impact Assessment';tab='Impact';}});},
    close(event){event.preventDefault();const f=Object.fromEntries(new FormData(event.target)),i=selected();action(async()=>{await request(`/api/workflow/incidents/${i.id}/close`,'POST',{revision:i.revision,...f});});},
    async downloadPdf(kind,button){const i=selected();if(!i)return;button.disabled=true;const label=button.textContent;button.textContent='Preparing PDF…';try{const response=await fetch(`/api/workflow/incidents/${encodeURIComponent(i.id)}/reports/${kind}.pdf`,{headers:live.token?{Authorization:'Bearer '+live.token}:{}});if(!response.ok){const error=await response.json().catch(()=>({}));throw Error(error.detail||error.error||'Report unavailable. Please sign in or complete the assessment.');}const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=`ResilientOps_${kind}_${i.id}_r${i.revision}.pdf`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Report downloaded.');}catch(error){toast(error.message);}finally{button.disabled=false;button.textContent=label;}},
    async download(){try{const response=await fetch(`/api/workflow/incidents/${selected().id}/report.eml`,{headers:live.token?{Authorization:'Bearer '+live.token}:{}});if(!response.ok)throw Error('Report unavailable');const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download='execution-report.eml';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){toast(error.message);}},
    async audit(){try{live.trace=await request(`/api/incidents/${selected().id}/trace`);render();}catch(error){toast(error.message);}},
    async table(name){live.table=name;live.offset=0;await flow.loadTable();},
    async page(delta){live.offset=Math.max(0,live.offset+50*delta);await flow.loadTable();},
    async loadTable(){const requestId=++live.tableRequest;live.tableLoading=true;live.error='';render();try{const reference=live.table.startsWith('reference:');const result=await request(`/api/data/${reference?'references':'tables'}/${encodeURIComponent(live.table.replace(/^reference:/,''))}?offset=${live.offset}&limit=50`);if(requestId!==live.tableRequest)return;live.tableRows=result.rows;live.total=result.total;}catch(error){if(requestId!==live.tableRequest)return;live.error=error.message;live.tableRows=[];toast(error.message);}finally{if(requestId===live.tableRequest){live.tableLoading=false;render();}}}

  };
  render();
  async function initialize(){
    live.loading=true;live.error='';live.authRequired=false;render();
    const results=await Promise.allSettled([request('/api/data/summary'),request('/api/scenarios'),request('/health'),refresh()]);
    const [summary,scenarios,health,incidents]=results;
    if(summary.status==='fulfilled'){live.summary=summary.value;window.workflowSummary=summary.value;}
    if(scenarios.status==='fulfilled')live.scenarios=scenarios.value;
    if(health.status==='fulfilled')live.health=health.value;
    const errors=results.filter(r=>r.status==='rejected').map(r=>r.reason);
    live.authRequired=errors.some(e=>e.status===401);
    live.error=errors.map(e=>e.message).join(' · ');
    if(incidents.status==='fulfilled'&&!live.rows.length&&live.summary?.dataset==='resilientops_data'){
      try{await request('/api/workflow/detect','POST',{});await refresh();}
      catch(error){live.error=[live.error,'Scenario scan: '+error.message].filter(Boolean).join(' · ');live.authRequired ||= error.status===401;}
    }
    live.loading=false;render();
  }
  initialize();
  setInterval(async()=>{if(live.busy||!live.rows.some(i=>['DETECTED','ANALYZING'].includes(i.status)))return;try{const before=JSON.stringify(selected());await refresh();if(!document.querySelector('form:focus-within')&&(view==='Overview'||view==='Incidents'||before!==JSON.stringify(selected())))render();}catch(error){toast(error.message);}},1500);
})();
